local plain = "0d000721"
local l1 = plain:reverse()
local xored = {}
for i = 1, #l1 do xored[i] = string.byte(l1, i) ~ 0x5A end
local hex = "0123456789abcdef"
local parts = {}
for i = 1, #xored do
  local b = xored[i]
  parts[#parts+1] = hex:sub((b>>4)+1,(b>>4)+1) .. hex:sub((b%16)+1,(b%16)+1)
end
local l3 = table.concat(parts)
local b64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function enc(data)
  local out={}
  for i=1,#data,3 do
    local a,b,c=data:byte(i,i+2); b=b or 0; c=c or 0
    local n=a*65536+b*256+c
    local n1,n2=i+1<=#data,i+2<=#data
    out[#out+1]=b64:sub((n>>18)%64+1,(n>>18)%64+1)
    out[#out+1]=b64:sub((n>>12)%64+1,(n>>12)%64+1)
    out[#out+1]=n1 and b64:sub((n>>6)%64+1,(n>>6)%64+1) or '='
    out[#out+1]=n2 and b64:sub(n%64+1,n%64+1) or '='
  end
  return table.concat(out)
end
print(enc(l3):reverse())
